(function(){'use strict';const KEY='ink-reading';const root=document.documentElement;const SITE_READING=(()=>{try{const node=document.getElementById('site-data');return JSON.parse((node&&node.textContent)||'{}').reading||{};}catch(e){return{};}})();const DEFAULTS={font:['serif','sans','mono'].indexOf(SITE_READING.font)!==-1?SITE_READING.font:'serif',size:Number(SITE_READING.font_size)||17,leading:Math.round((Number(SITE_READING.line_height)||1.7)*10),width:Number(SITE_READING.width)||100,focus:false,calm:false};let settings=Object.assign({},DEFAULTS);function read(){try{const raw=JSON.parse(localStorage.getItem(KEY)||'{}');settings=Object.assign({},DEFAULTS,raw);}catch(e){settings=Object.assign({},DEFAULTS);}}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(settings));}catch(e){}}
function applySettings(){root.setAttribute('data-font',settings.font);root.style.setProperty('--read-size',settings.size+'px');root.style.setProperty('--read-leading',(settings.leading/10).toFixed(2));root.style.setProperty('--read-width',settings.width>=100?'100%':settings.width+'rem');root.setAttribute('data-focus',settings.focus?'on':'off');root.setAttribute('data-calm',settings.calm?'on':'off');if(settings.calm)root.classList.remove('ink-anim');else if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)root.classList.add('ink-anim');syncControls();document.dispatchEvent(new CustomEvent('ink:reading',{detail:settings}));}
function syncControls(){document.querySelectorAll('[data-setting]').forEach((node)=>{const key=node.getAttribute('data-setting');if(node.tagName==='INPUT'){node.value=key==='leading'?settings.leading:settings[key];}else if(node.classList.contains('seg')){node.querySelectorAll('button').forEach((btn)=>{btn.classList.toggle('is-on',btn.getAttribute('data-value')===settings.font);});}});document.querySelectorAll('[data-out]').forEach((node)=>{const key=node.getAttribute('data-out');if(key==='leading')node.textContent=(settings.leading/10).toFixed(1);else if(key==='size')node.textContent=settings.size+'px';else if(key==='width')node.textContent=settings.width>=100?'全宽':settings.width+'rem';});document.querySelectorAll('[data-toggle]').forEach((node)=>{const key=node.getAttribute('data-toggle');node.setAttribute('aria-pressed',String(Boolean(settings[key])));});}
function initSettings(){read();applySettings();document.querySelectorAll('[data-setting]').forEach((node)=>{if(node.tagName==='INPUT'){node.addEventListener('input',()=>{const key=node.getAttribute('data-setting');settings[key]=Number(node.value);persist();applySettings();});}else{node.querySelectorAll('button').forEach((btn)=>{btn.addEventListener('click',()=>{settings.font=btn.getAttribute('data-value');persist();applySettings();});});}});document.querySelectorAll('[data-toggle]').forEach((node)=>{node.addEventListener('click',()=>{const key=node.getAttribute('data-toggle');settings[key]=!settings[key];persist();applySettings();});});document.querySelectorAll('[data-action="reset-settings"]').forEach((btn)=>{btn.addEventListener('click',()=>{settings=Object.assign({},DEFAULTS);persist();applySettings();});});}
let progressHandler=null;function initProgress(){const wrap=document.querySelector('[data-progress]');const bar=document.querySelector('[data-progress-bar]');const prose=document.getElementById('post-content')||document.querySelector('.ink-prose');if(progressHandler){window.removeEventListener('scroll',progressHandler);window.removeEventListener('resize',progressHandler);progressHandler=null;}
if(!wrap||!bar||!prose){if(wrap)wrap.hidden=true;return;}
wrap.hidden=false;progressHandler=()=>{const rect=prose.getBoundingClientRect();const total=rect.height-window.innerHeight*0.6;const passed=-rect.top+window.innerHeight*0.25;const ratio=total>0?Math.min(1,Math.max(0,passed/total)):(rect.top<0?1:0);bar.style.width=(ratio*100).toFixed(2)+'%';};progressHandler();window.addEventListener('scroll',progressHandler,{passive:true});window.addEventListener('resize',progressHandler,{passive:true});}
let tocHandler=null;function initToc(){const list=document.querySelector('[data-toc-list]');const prose=document.getElementById('post-content')||document.querySelector('.ink-prose');if(tocHandler){window.removeEventListener('scroll',tocHandler);window.removeEventListener('resize',tocHandler);tocHandler=null;}
if(!list||!prose)return;const links=[...list.querySelectorAll('a[data-anchor]')];if(!links.length)return;const targets=links.map((link)=>document.getElementById(decodeURIComponent(link.getAttribute('data-anchor')))).filter(Boolean);const positions=()=>targets.map((node)=>node.getBoundingClientRect().top+window.scrollY);let activeIndex=-1;const keepVisible=(link)=>{const item=link.getBoundingClientRect();const box=list.getBoundingClientRect();if(item.top<box.top)list.scrollTop+=item.top-box.top;else if(item.bottom>box.bottom)list.scrollTop+=item.bottom-box.bottom;};tocHandler=()=>{const line=window.scrollY+140;const tops=positions();let index=0;tops.forEach((top,i)=>{if(top<=line)index=i;});if(index===activeIndex)return;activeIndex=index;links.forEach((link,i)=>link.classList.toggle('is-active',i===index));keepVisible(links[index]);};tocHandler();window.addEventListener('scroll',tocHandler,{passive:true});window.addEventListener('resize',tocHandler,{passive:true});}
const ANCHOR_TOP=84;let alignTimer=null;function stopAlign(){if(alignTimer){clearInterval(alignTimer);alignTimer=null;}}
function alignAnchor(){const id=decodeURIComponent((location.hash||'').replace(/^#/,''));if(!id)return;stopAlign();const deadline=performance.now()+1800;let okCount=0;alignTimer=setInterval(()=>{const target=document.getElementById(id);if(!target||performance.now()>deadline){stopAlign();return;}
const top=target.getBoundingClientRect().top;if(Math.abs(top-ANCHOR_TOP)>60){window.scrollTo({top:Math.max(0,top+window.scrollY-ANCHOR_TOP),behavior:'instant'});okCount=0;}else if(++okCount>=2){stopAlign();}},70);}
window.addEventListener('hashchange',alignAnchor);['wheel','touchstart','keydown'].forEach((type)=>window.addEventListener(type,stopAlign,{passive:true}));document.addEventListener('click',(event)=>{const anchor=event.target&&event.target.closest?event.target.closest('a[href*="#"]'):null;if(anchor)setTimeout(alignAnchor,250);},true);function initKeys(){document.addEventListener('keydown',(event)=>{const tag=(event.target.tagName||'').toLowerCase();if(tag==='input'||tag==='textarea'||event.target.isContentEditable)return;if(event.key==='j'||event.key==='J'){const next=document.querySelector('.post__nav-item--next');if(next&&next.href)location.href=next.href;}else if(event.key==='k'||event.key==='K'){const prev=document.querySelector('.post__nav-item--prev');if(prev&&prev.href)location.href=prev.href;}else if(event.key==='g'||event.key==='G'){window.scrollTo({top:0,behavior:'smooth'});}});}
document.addEventListener('DOMContentLoaded',()=>{initSettings();initProgress();initToc();initKeys();if(location.hash)alignAnchor();});document.addEventListener('ink:navigate',()=>{initProgress();initToc();});window.InkReading={get:()=>settings,set:(patch)=>{Object.assign(settings,patch);persist();applySettings();}};})();